use std::collections::BTreeMap;
use std::fs::File;
use std::io::{Read, Seek, SeekFrom};
use std::path::{Path, PathBuf};

const MAGIC: &[u8; 4] = b"GGUF";
const DEFAULT_ALIGNMENT: u64 = 32;
const QK_K: u64 = 256;

#[derive(Clone, Debug, PartialEq)]
pub enum GgufValue { U8(u8), I8(i8), U16(u16), I16(i16), U32(u32), I32(i32), F32(f32), Bool(bool), String(String), Array(Vec<GgufValue>), U64(u64), I64(i64), F64(f64) }
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct GgufTensorInfo { pub name: String, pub shape: Vec<u64>, pub dtype: u32, pub offset: u64 }
pub struct GgufReader { path: PathBuf, file: File, pub version: u32, pub metadata: BTreeMap<String, GgufValue>, pub tensors: Vec<GgufTensorInfo>, data_start: u64 }

struct Reader<'a> { file: &'a mut File }
impl<'a> Reader<'a> {
    fn bytes(&mut self,n:usize)->Result<Vec<u8>,String>{let mut b=vec![0u8;n];self.file.read_exact(&mut b).map_err(|e|e.to_string())?;Ok(b)}
    fn u8(&mut self)->Result<u8,String>{Ok(self.bytes(1)?[0])} fn i8(&mut self)->Result<i8,String>{Ok(self.u8()? as i8)}
    fn u16(&mut self)->Result<u16,String>{let b=self.bytes(2)?;Ok(u16::from_le_bytes([b[0],b[1]]))} fn i16(&mut self)->Result<i16,String>{Ok(self.u16()? as i16)}
    fn u32(&mut self)->Result<u32,String>{let b=self.bytes(4)?;Ok(u32::from_le_bytes(b.try_into().unwrap()))} fn i32(&mut self)->Result<i32,String>{Ok(self.u32()? as i32)}
    fn u64(&mut self)->Result<u64,String>{let b=self.bytes(8)?;Ok(u64::from_le_bytes(b.try_into().unwrap()))} fn i64(&mut self)->Result<i64,String>{Ok(self.u64()? as i64)}
    fn f32(&mut self)->Result<f32,String>{Ok(f32::from_bits(self.u32()?))} fn f64(&mut self)->Result<f64,String>{Ok(f64::from_bits(self.u64()?))}
    fn string(&mut self)->Result<String,String>{let n=usize::try_from(self.u64()?).map_err(|_|"GGUF string is too large")?;String::from_utf8(self.bytes(n)?).map_err(|e|format!("invalid UTF-8 in GGUF string: {e}"))}
    fn value(&mut self,ty:u32)->Result<GgufValue,String>{match ty{0=>Ok(GgufValue::U8(self.u8()?)),1=>Ok(GgufValue::I8(self.i8()?)),2=>Ok(GgufValue::U16(self.u16()?)),3=>Ok(GgufValue::I16(self.i16()?)),4=>Ok(GgufValue::U32(self.u32()?)),5=>Ok(GgufValue::I32(self.i32()?)),6=>Ok(GgufValue::F32(self.f32()?)),7=>Ok(GgufValue::Bool(self.u8()?!=0)),8=>Ok(GgufValue::String(self.string()?)),9=>{let et=self.u32()?;let n=usize::try_from(self.u64()?).map_err(|_|"GGUF array is too large")?;let mut v=Vec::with_capacity(n);for _ in 0..n{v.push(self.value(et)?);}Ok(GgufValue::Array(v))},10=>Ok(GgufValue::U64(self.u64()?)),11=>Ok(GgufValue::I64(self.i64()?)),12=>Ok(GgufValue::F64(self.f64()?)),_=>Err(format!("unsupported GGUF metadata type {ty}"))}}
}
fn align(v:u64,a:u64)->Result<u64,String>{if a==0||!a.is_power_of_two(){return Err(format!("invalid GGUF alignment {a}"));}v.checked_add(a-1).map(|x|x/a*a).ok_or_else(||"GGUF offset overflow".into())}
fn element_count(s:&[u64])->Result<u64,String>{s.iter().try_fold(1u64,|a,&b|a.checked_mul(b)).ok_or_else(||"tensor element count overflow".into())}
fn block_size(t:u32)->Option<(u64,u64)>{match t{2=>Some((32,18)),3=>Some((32,20)),6=>Some((32,22)),7=>Some((32,24)),8=>Some((32,34)),9=>Some((32,36)),10=>Some((QK_K,84)),11=>Some((QK_K,110)),12=>Some((QK_K,144)),13=>Some((QK_K,176)),14=>Some((QK_K,210)),_=>None}}

impl GgufReader {
    pub fn open(path:impl AsRef<Path>)->Result<Self,String>{
        let path=path.as_ref().to_path_buf();let mut file=File::open(&path).map_err(|e|e.to_string())?;let mut magic=[0u8;4];file.read_exact(&mut magic).map_err(|e|e.to_string())?;if &magic!=MAGIC{return Err("not a GGUF file".into());}
        let mut r=Reader{file:&mut file};let version=r.u32()?;if !(2..=3).contains(&version){return Err(format!("unsupported GGUF version {version}"));}let tensor_count=r.u64()?;let metadata_count=r.u64()?;let mut metadata=BTreeMap::new();
        for _ in 0..metadata_count{let key=r.string()?;let ty=r.u32()?;metadata.insert(key,r.value(ty)?);}let tc=usize::try_from(tensor_count).map_err(|_|"too many GGUF tensors")?;let mut tensors=Vec::with_capacity(tc);
        for _ in 0..tc{let name=r.string()?;let dims=usize::try_from(r.u32()?).map_err(|_|"too many tensor dimensions")?;let mut shape=Vec::with_capacity(dims);for _ in 0..dims{shape.push(r.u64()?);}let dtype=r.u32()?;let offset=r.u64()?;tensors.push(GgufTensorInfo{name,shape,dtype,offset});}
        let pos=r.file.stream_position().map_err(|e|e.to_string())?;let alignment=match metadata.get("general.alignment"){Some(GgufValue::U32(x))=>u64::from(*x),Some(GgufValue::U64(x))=>*x,None=>DEFAULT_ALIGNMENT,_=>return Err("general.alignment must be an integer".into())};let data_start=align(pos,alignment)?;Ok(Self{path,file,version,metadata,tensors,data_start})
    }
    pub fn path(&self)->&Path{&self.path} pub fn tensor(&self,name:&str)->Option<&GgufTensorInfo>{self.tensors.iter().find(|t|t.name==name)}
    fn tensor_size(info:&GgufTensorInfo)->Result<usize,String>{let n=element_count(&info.shape)?;let b=match info.dtype{0=>n.checked_mul(4),1|30=>n.checked_mul(2),24=>Some(n),25=>n.checked_mul(2),26=>n.checked_mul(4),27|28=>n.checked_mul(8),2|3|6|7|8|9|10|11|12|13|14=>{let(bl,s)=block_size(info.dtype).unwrap();if n%bl!=0{return Err(format!("tensor '{}' has {} elements, not divisible by quant block size {}",info.name,n,bl));}n.checked_div(bl).and_then(|x|x.checked_mul(s))},_=>None}.ok_or_else(||format!("unsupported GGML type {} ({})",info.dtype,gguf_dtype_name(info.dtype)))?;usize::try_from(b).map_err(|_|"tensor is too large for memory".into())}
    pub fn tensor_bytes(&mut self,name:&str)->Result<Vec<u8>,String>{let info=self.tensor(name).cloned().ok_or_else(||format!("GGUF tensor '{name}' not found"))?;let size=Self::tensor_size(&info)?;let start=self.data_start.checked_add(info.offset).ok_or("tensor offset overflow")?;let end=start.checked_add(u64::try_from(size).map_err(|_|"tensor size overflow")?).ok_or("tensor end overflow")?;if end>self.file.metadata().map_err(|e|e.to_string())?.len(){return Err(format!("tensor '{}' extends past end of GGUF file",info.name));}self.file.seek(SeekFrom::Start(start)).map_err(|e|e.to_string())?;let mut bytes=vec![0u8;size];self.file.read_exact(&mut bytes).map_err(|e|e.to_string())?;Ok(bytes)}
    pub fn tensor_f32(&mut self,name:&str)->Result<Vec<f32>,String>{let info=self.tensor(name).cloned().ok_or_else(||format!("GGUF tensor '{name}' not found"))?;let bytes=self.tensor_bytes(name)?;match info.dtype{0=>Ok(bytes.chunks_exact(4).map(|b|f32::from_le_bytes(b.try_into().unwrap())).collect()),1=>Ok(bytes.chunks_exact(2).map(|b|f16_to_f32(u16::from_le_bytes([b[0],b[1]]))).collect()),30=>Ok(bytes.chunks_exact(2).map(|b|f32::from_bits(u32::from(u16::from_le_bytes([b[0],b[1]]))<<16)).collect()),24=>Ok(bytes.into_iter().map(|x|x as i8 as f32).collect()),25=>Ok(bytes.chunks_exact(2).map(|b|i16::from_le_bytes([b[0],b[1]]) as f32).collect()),26=>Ok(bytes.chunks_exact(4).map(|b|i32::from_le_bytes(b.try_into().unwrap()) as f32).collect()),27=>Ok(bytes.chunks_exact(8).map(|b|i64::from_le_bytes(b.try_into().unwrap()) as f32).collect()),28=>Ok(bytes.chunks_exact(8).map(|b|f64::from_le_bytes(b.try_into().unwrap()) as f32).collect()),2=>Ok(decode_q4_0(&bytes)),3=>Ok(decode_q4_1(&bytes)),6=>Ok(decode_q5_0(&bytes)),7=>Ok(decode_q5_1(&bytes)),8=>Ok(decode_q8_0(&bytes)),9=>Ok(decode_q8_1(&bytes)),10=>Ok(decode_q2_k(&bytes)),11=>Ok(decode_q3_k(&bytes)),12=>Ok(decode_q4_k(&bytes)),13=>Ok(decode_q5_k(&bytes)),14=>Ok(decode_q6_k(&bytes)),_=>Err(format!("tensor '{}' uses unsupported GGML type {} ({})",info.name,info.dtype,gguf_dtype_name(info.dtype)))}}
}

fn read_f16(b:&[u8])->f32{f16_to_f32(u16::from_le_bytes([b[0],b[1]]))} fn read_f32(b:&[u8])->f32{f32::from_le_bytes(b[..4].try_into().unwrap())}
fn decode_q4_0(b:&[u8])->Vec<f32>{let mut o=Vec::with_capacity(b.len()/18*32);for x in b.chunks_exact(18){let d=read_f16(&x[..2]);for i in 0..32{let q=if i&1==0{x[2+i/2]&15}else{x[2+i/2]>>4};o.push(d*(q as f32-8.0));}}o}
fn decode_q4_1(b:&[u8])->Vec<f32>{let mut o=Vec::with_capacity(b.len()/20*32);for x in b.chunks_exact(20){let d=read_f16(&x[..2]);let m=read_f16(&x[2..4]);for i in 0..32{let q=if i&1==0{x[4+i/2]&15}else{x[4+i/2]>>4};o.push(d*q as f32+m);}}o}
fn decode_q5_0(b:&[u8])->Vec<f32>{let mut o=Vec::with_capacity(b.len()/22*32);for x in b.chunks_exact(22){let d=read_f16(&x[..2]);let qh=u32::from_le_bytes(x[2..6].try_into().unwrap());for i in 0..32{let q=if i&1==0{x[6+i/2]&15}else{x[6+i/2]>>4};o.push(d*((q|(((qh>>i)&1)as u8)<<4)as f32-16.0));}}o}
fn decode_q5_1(b:&[u8])->Vec<f32>{let mut o=Vec::with_capacity(b.len()/24*32);for x in b.chunks_exact(24){let d=read_f16(&x[..2]);let m=read_f16(&x[2..4]);let qh=u32::from_le_bytes(x[4..8].try_into().unwrap());for i in 0..32{let q=if i&1==0{x[8+i/2]&15}else{x[8+i/2]>>4};o.push(d*(q|(((qh>>i)&1)as u8)<<4)as f32+m);}}o}
fn decode_q8_0(b:&[u8])->Vec<f32>{let mut o=Vec::with_capacity(b.len()/34*32);for x in b.chunks_exact(34){let d=read_f16(&x[..2]);for i in 0..32{o.push(d*x[2+i]as i8 as f32);}}o}
fn decode_q8_1(b:&[u8])->Vec<f32>{let mut o=Vec::with_capacity(b.len()/36*32);for x in b.chunks_exact(36){let d=read_f32(&x[..4]);for i in 0..32{o.push(d*x[8+i]as i8 as f32);}}o}

fn decode_q2_k(b:&[u8])->Vec<f32>{let mut o=Vec::with_capacity(b.len()/84*256);for x in b.chunks_exact(84){let d=read_f16(&x[80..82]);let min=read_f16(&x[82..84]);let scales=&x[..16];let q=&x[16..80];let mut is=0;for half in 0..2{let mut shift=0;for _ in 0..4{let sc=scales[is];is+=1;let dl=d*(sc&15)as f32;let ml=min*(sc>>4)as f32;for l in 0..16{o.push(dl*((q[half*32+l]>>shift)&3)as f32-ml);}let sc=scales[is];is+=1;let dl=d*(sc&15)as f32;let ml=min*(sc>>4)as f32;for l in 0..16{o.push(dl*((q[half*32+16+l]>>shift)&3)as f32-ml);}shift+=2;}}}o}
fn decode_q3_k(b:&[u8])->Vec<f32>{let mut o=Vec::with_capacity(b.len()/110*256);for x in b.chunks_exact(110){let mut a=[0u32;4];a[0]=u32::from_le_bytes(x[96..100].try_into().unwrap());a[1]=u32::from_le_bytes(x[100..104].try_into().unwrap());a[2]=u32::from_le_bytes(x[104..108].try_into().unwrap());let tmp=a[2];a[2]=((a[0]>>4)&0x0f0f0f0f)|(((tmp>>4)&0x03030303)<<4);a[3]=((a[1]>>4)&0x0f0f0f0f)|(((tmp>>6)&0x03030303)<<4);a[0]=(a[0]&0x0f0f0f0f)|(((tmp)&0x03030303)<<4);a[1]=(a[1]&0x0f0f0f0f)|(((tmp>>2)&0x03030303)<<4);let sc=a.iter().flat_map(|v|v.to_le_bytes()).collect::<Vec<_>>();let d=read_f16(&x[108..110]);let q=&x[..64];let hm=&x[64..96];let mut is=0;let mut m=1u8;for half in 0..2{let mut shift=0;for _ in 0..4{let dl=d*(sc[is]as i8 as f32-32.0);is+=1;for l in 0..16{o.push(dl*(((q[half*32+l]>>shift)&3)as i8 as f32-if hm[l]&m!=0{0.0}else{4.0}));}let dl=d*(sc[is]as i8 as f32-32.0);is+=1;for l in 0..16{o.push(dl*(((q[half*32+16+l]>>shift)&3)as i8 as f32-if hm[l+16]&m!=0{0.0}else{4.0}));}shift+=2;m<<=1;}}}o}
fn get_scale_min_k4(j:usize,q:&[u8])->(u8,u8){if j<4{(q[j]&63,q[j+4]&63)}else{((q[j+4]&15)|((q[j-4]>>6)<<4),(q[j+4]>>4)|((q[j]>>6)<<4))}}
fn decode_q4_k(b:&[u8])->Vec<f32>{let mut o=Vec::with_capacity(b.len()/144*256);for x in b.chunks_exact(144){let d=read_f16(&x[..2]);let min=read_f16(&x[2..4]);let sc=&x[4..16];let q=&x[16..144];for span in 0..4{let(s1,m1)=get_scale_min_k4(span*2,sc);let(s2,m2)=get_scale_min_k4(span*2+1,sc);let q=&q[span*32..span*32+32];for &v in q{o.push(d*s1 as f32*(v&15)as f32-min*m1 as f32);}for &v in q{o.push(d*s2 as f32*(v>>4)as f32-min*m2 as f32);}}}o}
fn decode_q5_k(b:&[u8])->Vec<f32>{let mut o=Vec::with_capacity(b.len()/176*256);for x in b.chunks_exact(176){let d=read_f16(&x[..2]);let min=read_f16(&x[2..4]);let sc=&x[4..16];let qh=&x[16..48];let q=&x[48..176];for span in 0..4{let(s1,m1)=get_scale_min_k4(span*2,sc);let(s2,m2)=get_scale_min_k4(span*2+1,sc);let u1=1u8<<(2*span);let u2=2u8<<(2*span);let q=&q[span*32..span*32+32];for l in 0..32{o.push(d*s1 as f32*((q[l]&15)+if qh[l]&u1!=0{16}else{0})as f32-min*m1 as f32);}for l in 0..32{o.push(d*s2 as f32*((q[l]>>4)+if qh[l]&u2!=0{16}else{0})as f32-min*m2 as f32);}}}o}
fn decode_q6_k(b:&[u8])->Vec<f32>{let mut o=Vec::with_capacity(b.len()/210*256);for x in b.chunks_exact(210){let d=read_f16(&x[208..210]);for half in 0..2{let ql=&x[half*64..half*64+64];let qh=&x[128+half*32..128+half*32+32];let sc=&x[192+half*8..192+half*8+8];for l in 0..32{let is=l/16;let q1=((ql[l]&15)as i32|(((qh[l]&3)as i32)<<4))-32;let q2=((ql[l+32]&15)as i32|((((qh[l]>>2)&3)as i32)<<4))-32;let q3=((ql[l]>>4)as i32|((((qh[l]>>4)&3)as i32)<<4))-32;let q4=((ql[l+32]>>4)as i32|((((qh[l]>>6)&3)as i32)<<4))-32;o.push(d*sc[is]as i8 as f32*q1 as f32);o.push(d*sc[is+2]as i8 as f32*q2 as f32);o.push(d*sc[is+4]as i8 as f32*q3 as f32);o.push(d*sc[is+6]as i8 as f32*q4 as f32);}}}o}

fn f16_to_f32(bits:u16)->f32{let sign=((bits as u32)&0x8000)<<16;let exp=((bits>>10)&0x1f)as u32;let frac=(bits&0x03ff)as u32;if exp==0{if frac==0{return f32::from_bits(sign);}let mut f=frac;let mut e=-14i32;while f&0x0400==0{f<<=1;e-=1;}f&=0x03ff;return f32::from_bits(sign|(((e+127)as u32)<<23)|(f<<13));}if exp==0x1f{return f32::from_bits(sign|0x7f800000|(frac<<13));}f32::from_bits(sign|((exp+112)<<23)|(frac<<13))}
pub fn gguf_dtype_name(t:u32)->&'static str{match t{0=>"F32",1=>"F16",2=>"Q4_0",3=>"Q4_1",6=>"Q5_0",7=>"Q5_1",8=>"Q8_0",9=>"Q8_1",10=>"Q2_K",11=>"Q3_K",12=>"Q4_K",13=>"Q5_K",14=>"Q6_K",15=>"Q8_K",16=>"IQ2_XXS",17=>"IQ2_XS",18=>"IQ3_XXS",19=>"IQ1_S",20=>"IQ4_NL",21=>"IQ3_S",22=>"IQ2_S",23=>"IQ4_XS",24=>"I8",25=>"I16",26=>"I32",27=>"I64",28=>"F64",29=>"IQ1_M",30=>"BF16",_=>"UNKNOWN"}}

#[cfg(test)]
mod tests{use super::*;#[test]fn half(){assert_eq!(f16_to_f32(0x3c00),1.0);assert_eq!(f16_to_f32(0xc000),-2.0);assert!(f16_to_f32(0x7c00).is_infinite());}#[test]fn alignment(){assert_eq!(align(33,32).unwrap(),64);assert!(align(33,24).is_err());}#[test]fn k_sizes(){assert_eq!(block_size(10),Some((256,84)));assert_eq!(block_size(11),Some((256,110)));assert_eq!(block_size(12),Some((256,144)));assert_eq!(block_size(13),Some((256,176)));assert_eq!(block_size(14),Some((256,210)));}#[test]fn zero_k_blocks(){assert!(decode_q2_k(&vec![0;84]).iter().all(|x|*x==0.0));assert!(decode_q3_k(&vec![0;110]).iter().all(|x|*x==0.0));assert!(decode_q4_k(&vec![0;144]).iter().all(|x|*x==0.0));assert!(decode_q5_k(&vec![0;176]).iter().all(|x|*x==0.0));assert!(decode_q6_k(&vec![0;210]).iter().all(|x|*x==0.0));}
#[test]fn q8_1_ignores_auxiliary_sum(){let mut block=vec![0u8;36];block[..4].copy_from_slice(&1.0f32.to_le_bytes());block[4..8].copy_from_slice(&123.0f32.to_le_bytes());block[8]=1;block[9]=u8::MAX;let values=decode_q8_1(&block);assert_eq!(values[0],1.0);assert_eq!(values[1],-1.0);assert!(values[2..].iter().all(|x|*x==0.0));}}
